		{long: "format", kind: kindChoice, choices: []string{"text", "json", "junit"}},
		{long: "json", kind: kindBool},
		{long: "experimental-verbose-json", kind: kindBool},
		{long: "junit", kind: kindBool},
		{long: "max-redirections", short: 'r', kind: kindInt},
		{long: "rate-limit", kind: kindInt},
		{long: "timeout", short: 't', kind: kindInt},
		{long: "verbose", short: 'v', kind: kindBool},
		{long: "proxy", kind: kindString},
		{long: "skip-tls-verification", kind: kindBool},
		{long: "one-page-only", kind: kindBool},
		{long: "color", kind: kindChoice, choices: []string{"auto", "always", "never"}},
		{long: "help", short: 'h', kind: kindBool},
		{long: "version", kind: kindBool},
	}
	longMap := make(map[string]*flagDef)
	shortMap := make(map[byte]*flagDef)
	for _, d := range defs {
		if d.short != 0 {
			d.display = fmt.Sprintf("-%c, --%s", d.short, d.long)
		} else {
			d.display = fmt.Sprintf("--%s", d.long)
		}
		longMap[d.long] = d
		if d.short != 0 {
			shortMap[d.short] = d
		}
	}
	return longMap, shortMap
}

func isOptionLike(s string) bool {
	if len(s) < 2 {
		return false
	}
	if s[0] != '-' {
		return false
	}
	if s == "--" {
		return true // treat as option? Actually -- alone is separator, but as value it should be considered option?
	}
	// single "-" alone is not option
	if s == "-" {
		return false
	}
	return true
}

// For int flags, check if s looks like a number (to accept "-1" as value)
func looksLikeIntValue(s string) bool {
	if len(s) == 0 {
		return false
	}
	// Must match ^-?[0-9] or ^\+?[0-9]? Actually "+1" doesn't start with "-", so not relevant for option check.
	// For option check, s starts with "-". So check second char is digit.
	if s[0] == '-' {
		if len(s) >= 2 {
			c := s[1]
			if c >= '0' && c <= '9' {
				return true
			}
		}
		return false
	}
	return true // doesn't start with "-", so it's a value
}

func parseCLI(args []string, opts *options) (positionals []string, errMsg string) {
	longMap, shortMap := buildFlagDefs()
	positionals = []string{}
	i := 0
	endOfFlags := false
	for i < len(args) {
		arg := args[i]
		if endOfFlags {
			positionals = append(positionals, arg)
			i++
			continue
		}
		if arg == "--" {
			endOfFlags = true
			i++
			continue
		}
		if arg == "-" {
			positionals = append(positionals, arg)
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			// long flag
			if len(arg) == 2 {
				// bare "--" already handled, but "--" with nothing? Actually arg=="--" handled above.
				// This is unreachable.
				positionals = append(positionals, arg)
				i++
				continue
			}
			nameVal := arg[2:]
			var name, val string
			var hasEq bool
			if idx := strings.Index(nameVal, "="); idx >= 0 {
				name = nameVal[:idx]
				val = nameVal[idx+1:]
				hasEq = true
			} else {
				name = nameVal
				hasEq = false
			}
			def, ok := longMap[name]
			if !ok {
				return nil, fmt.Sprintf("unknown flag `%s'", name)
			}
			if def.kind == kindBool {
				if hasEq {
					return nil, fmt.Sprintf("bool flag `%s' cannot have an argument", def.display)
				}
				// set bool
				setBool(opts, def.long, true)
				i++
				continue
			}
			// value flag
			var value string
			if hasEq {
				value = val
			} else {
				// need next arg
				if i+1 >= len(args) {
					return nil, fmt.Sprintf("expected argument for flag `%s'", def.display)
				}
				next := args[i+1]
				// check if next is option-like
				shouldTreatAsOption := false
				if isOptionLike(next) {
					if def.kind == kindInt {
						// accept if looks like int value (e.g., "-1")
						if !looksLikeIntValue(next) {
							shouldTreatAsOption = true
						}
					} else {
						// for all other kinds (uint, string, choice), any option-like is option
						shouldTreatAsOption = true
					}
				}
				if shouldTreatAsOption {
					return nil, fmt.Sprintf("expected argument for flag `%s', but got option `%s'", def.display, next)
				}
				value = next
				i++ // consume next
			}
			// assign value
			if msg := assignValue(opts, def, value); msg != "" {
				return nil, msg
			}
			i++
			continue
		}
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// short flags, possibly combined
			// iterate chars
			consumedNext := false
			failed := false
			var failMsg string
			// We need to handle index i advancement for value consuming next arg
			// Parse chars in this arg
			j := 1
			for j < len(arg) {
				c := arg[j]
				def, ok := shortMap[c]
				if !ok {
					failMsg = fmt.Sprintf("unknown flag `%c'", c)
					failed = true
					break
				}
				if def.kind == kindBool {
					setBool(opts, def.long, true)
					j++
					continue
				}
				// value flag
				if j == 1 {
					// first flag in arg, rest is value (if any)
					rest := ""
					if j+1 < len(arg) {
						rest = arg[j+1:]
					}
					if len(rest) > 0 {
						// strip leading "=" if present
						if rest[0] == '=' {
							rest = rest[1:]
						}
						if msg := assignValue(opts, def, rest); msg != "" {
							failMsg = msg
							failed = true
							break
						}
						// done with this arg
						j = len(arg)
						break
					} else {
						// need next arg
						if i+1 >= len(args) {
							failMsg = fmt.Sprintf("expected argument for flag `%s'", def.display)
							failed = true
							break
						}
						next := args[i+1]
						shouldTreatAsOption := false
						if isOptionLike(next) {
							if def.kind == kindInt {
								if !looksLikeIntValue(next) {
									shouldTreatAsOption = true
								}
							} else {
								shouldTreatAsOption = true
							}
						}
						if shouldTreatAsOption {
							failMsg = fmt.Sprintf("expected argument for flag `%s', but got option `%s'", def.display, next)
							failed = true
							break
						}
						if msg := assignValue(opts, def, next); msg != "" {
							failMsg = msg
							failed = true
							break
						}
						consumedNext = true
						j = len(arg)
						break
					}
				} else {
					// value flag not first in combined
					restExists := (j+1 < len(arg))
					if restExists {
						// error expected argument (ignore rest and next)
						failMsg = fmt.Sprintf("expected argument for flag `%s'", def.display)
						failed = true
						break
					} else {
						// last char, need next arg
						if i+1 >= len(args) {
							failMsg = fmt.Sprintf("expected argument for flag `%s'", def.display)
							failed = true
							break
						}
						next := args[i+1]
						shouldTreatAsOption := false
						if isOptionLike(next) {
							if def.kind == kindInt {
								if !looksLikeIntValue(next) {
									shouldTreatAsOption = true
								}
							} else {
								shouldTreatAsOption = true
							}
						}
						if shouldTreatAsOption {
							failMsg = fmt.Sprintf("expected argument for flag `%s', but got option `%s'", def.display, next)
							failed = true
							break
						}
						if msg := assignValue(opts, def, next); msg != "" {
							failMsg = msg
							failed = true
							break
						}
						consumedNext = true
						j = len(arg)
						break
					}
				}
			}
			if failed {
				return nil, failMsg
			}
			i++
			if consumedNext {
				i++
			}
			continue
		}
		// positional
		positionals = append(positionals, arg)
		i++
	}
	return positionals, ""
}

func setBool(opts *options, long string, v bool) {
	switch long {
	case "follow-robots-txt":
		opts.followRobotsTxt = v
	case "follow-sitemap-xml":
		opts.followSitemapXml = v
	case "ignore-fragments":
		opts.ignoreFragments = v
	case "json":
		opts.jsonFlag = v
	case "experimental-verbose-json":
		opts.expVerboseJson = v
	case "junit":
		opts.junitFlag = v
	case "verbose":
		opts.verbose = v
	case "skip-tls-verification":
		opts.skipTLS = v
	case "one-page-only":
		opts.onePageOnly = v
	case "help":
		opts.helpFlag = v
	case "version":
		opts.versionFlag = v
	}
}

func assignValue(opts *options, def *flagDef, value string) string {
	switch def.long {
	case "accepted-status-codes":
		opts.acceptedCodes = value
		return ""
	case "buffer-size":
		n, err := strconv.ParseInt(value, 0, 64)
		if err != nil {
			return fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", def.display, err.Error())
		}
		opts.bufferSize = int(n)
		return ""
	case "max-connections":
		n, err := strconv.ParseInt(value, 0, 64)
		if err != nil {
			return fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", def.display, err.Error())
		}
		opts.maxConnections = int(n)
		return ""
	case "max-connections-per-host":
		n, err := strconv.ParseInt(value, 0, 64)
		if err != nil {
			return fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", def.display, err.Error())
		}
		opts.maxConnectionsPerHost = int(n)
		return ""
	case "max-response-body-size":
		n, err := strconv.ParseInt(value, 0, 64)
		if err != nil {
			return fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", def.display, err.Error())
		}
		opts.maxResponseBodySize = int(n)
		return ""
	case "exclude":
		opts.exclude = append(opts.exclude, value)
		return ""
	case "include":
		opts.include = append(opts.include, value)
		return ""
	case "header":
		opts.headers = append(opts.headers, value)
		return ""
	case "max-retries":
		n, err := strconv.ParseUint(value, 0, 64)
		if err != nil {
			return fmt.Sprintf("invalid argument for flag `%s' (expected uint): %s", def.display, err.Error())
		}
		opts.maxRetries = n
		opts.maxRetriesSet = true
		return ""
	case "dns-resolver":
		opts.dnsResolver = value
		return ""
	case "format":
		for _, c := range def.choices {
			if value == c {
				opts.format = value
				opts.formatSet = true
				return ""
			}
		}
		return fmt.Sprintf("Invalid value `%s' for option `--%s'. Allowed values are: text, json or junit", value, def.long)
	case "max-redirections":
		n, err := strconv.ParseInt(value, 0, 64)
		if err != nil {
			return fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", def.display, err.Error())
		}
		opts.maxRedirections = int(n)
		return ""
	case "rate-limit":
		n, err := strconv.ParseInt(value, 0, 64)
		if err != nil {
			return fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", def.display, err.Error())
		}
		opts.rateLimit = int(n)
		opts.rateLimitSet = true
		return ""
	case "timeout":
		n, err := strconv.ParseInt(value, 0, 64)
		if err != nil {
			return fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", def.display, err.Error())
		}
		opts.timeout = int(n)
		return ""
	case "proxy":
		opts.proxy = value
		return ""
	case "color":
		for _, c := range def.choices {
			if value == c {
				opts.color = value
				return ""
			}
		}
		return fmt.Sprintf("Invalid value `%s' for option `--%s'. Allowed values are: auto, always or never", value, def.long)
	}
	return ""
}

func printHelp(prog string) string {
	// Exact help text, prog name substituted
	// Note: help ends with newline
	help := "Usage:\n" +
		"  " + prog + " [options] <url>\n" +
		"\n" +
		"Application Options:\n" +
		"      --accepted-status-codes=<codes>       Accepted HTTP response status codes\n" +
		"                                            (e.g. '200..300,403') (default:\n" +
		"                                            200..300)\n" +
		"  -b, --buffer-size=<size>                  HTTP response buffer size in bytes\n" +
		"                                            (default: 4096)\n" +
		"  -c, --max-connections=<count>             Maximum number of HTTP connections\n" +
		"                                            (default: 512)\n" +
		"      --max-connections-per-host=<count>    Maximum number of HTTP connections\n" +
		"                                            per host (default: 512)\n" +
		"      --max-response-body-size=<size>       Maximum response body size to read\n" +
		"                                            (default: 10000000)\n" +
		"  -e, --exclude=<pattern>...                Exclude URLs matched with given\n" +
		"                                            regular expressions\n" +
		"  -i, --include=<pattern>...                Include URLs matched with given\n" +
		"                                            regular expressions\n" +
		"      --follow-robots-txt                   Follow robots.txt when scraping\n" +
		"                                            pages\n" +
		"      --follow-sitemap-xml                  Scrape only pages listed in\n" +
		"                                            sitemap.xml (deprecated)\n" +
		"      --header=<header>...                  Custom headers\n" +
		"  -f, --ignore-fragments                    Ignore URL fragments\n" +
		"      --max-retries=<count>                 Maximum retry count for network\n" +
		"                                            errors (default: 0)\n" +
		"      --dns-resolver=<address>              Custom DNS resolver\n" +
		"      --format=[text|json|junit]            Output format (default: text)\n" +
		"      --json                                Output results in JSON (deprecated)\n" +
		"      --experimental-verbose-json           Include successful results in JSON\n" +
		"                                            (deprecated)\n" +
		"      --junit                               Output results as JUnit XML file\n" +
		"                                            (deprecated)\n" +
		"  -r, --max-redirections=<count>            Maximum number of redirections\n" +
		"                                            (default: 64)\n" +
		"      --rate-limit=<rate>                   Max requests per second\n" +
		"  -t, --timeout=<seconds>                   Timeout for HTTP requests in\n" +
		"                                            seconds (default: 10)\n" +
		"  -v, --verbose                             Show successful results too\n" +
		"      --proxy=<host>                        HTTP proxy host\n" +
		"      --skip-tls-verification               Skip TLS certificate verification\n" +
		"      --one-page-only                       Only check links found in the given\n" +
		"                                            URL\n" +
		"      --color=[auto|always|never]           Color output (default: auto)\n" +
		"  -h, --help                                Show this help\n" +
		"      --version                             Show version\n"
	return help
}

func main() {
	prog := filepath.Base(os.Args[0])
	opts := defaultOptions()
	positionals, errMsg := parseCLI(os.Args[1:], opts)
	if errMsg != "" {
		// stderr color is always auto (tty ? red : plain), ignoring --color flag
		// For now, print plain; color handling later
		msg := errMsg + "\n"
		if isTerminal(os.Stderr) {
			fmt.Fprintf(os.Stderr, "\x1b[31m%s\x1b[0m", msg)
		} else {
			fmt.Fprint(os.Stderr, msg)
		}
		os.Exit(1)
	}
	if opts.helpFlag {
		fmt.Fprint(os.Stdout, printHelp(prog))
		os.Exit(0)
	}
	if opts.versionFlag {
		fmt.Fprintln(os.Stdout, versionStr)
		os.Exit(0)
	}
	if len(positionals) != 1 {
		msg := "invalid number of arguments\n"
		if isTerminal(os.Stderr) {
			fmt.Fprintf(os.Stderr, "\x1b[31m%s\x1b[0m", msg)
		} else {
			fmt.Fprint(os.Stderr, msg)
		}
		os.Exit(1)
	}
	// TODO: run crawler
	url := positionals[0]
	_ = url
	_ = opts
	// placeholder
	fmt.Fprintln(os.Stderr, "not implemented")
	os.Exit(1)
}

func isTerminal(f *os.File) bool {
	// check if file is a terminal
	// Use Stat and ModeCharDevice
	stat, err := f.Stat()
	if err != nil {
		return false
	}
	return (stat.Mode() & os.ModeCharDevice) != 0
}
