		return false
	}
	// Control chars? Exclude?
	if c < 0x20 {
		return false
	}
	return true
}

func parseSrcset(s string) []string {
	// Split on ",", for each part, trim, take first token (split on whitespace)
	var res []string
	parts := strings.Split(s, ",")
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		// Split on whitespace, take first
