	if len(rules) == 0 {
		return true // no rules => allow
	}
	// Find longest matching rule
	longestLen := -1
	longestAllow := true // default allow if no match
	// For tie (same length, one Allow one Disallow), Allow wins? Per Google spec, Allow wins on tie. We'll implement: if same length, prefer Allow.
	for _, r := range rules {
		if r.pattern == "" {
			// Empty Disallow matches nothing (allow). Empty Allow? Empty Allow also matches nothing? Per spec, Allow with empty? Unclear. Treat as no match.
			continue
		}
