			l := len(r.pattern)
			if l > longestLen {
				longestLen = l
				longestAllow = r.allow
			} else if l == longestLen {
				// Tie: Allow wins
				if r.allow {
					longestAllow = true
				}
			}
		}
	}
	if longestLen == -1 {
		return true // no match => allow
	}
	return longestAllow
}

func robotsMatch(pattern, path string) bool {
	// Handle "*" and "$" per Google spec.
	// If pattern contains "*" or ends with "$", convert to regex.
	if strings.Contains(pattern, "*") || strings.HasSuffix(pattern, "$") {
		// Convert to regex: escape all regex meta except "*", handle "$" at end as end anchor.
		// Pattern is prefix match unless ends with "$" (exact end).
		// Implementation: build regex "^" + escaped + (if ends with "$" ? "$" : ".*"? No, prefix match means "^escaped" (without ".*", since prefix). Actually for prefix match, regex "^escaped" will match prefix (since Go's MatchString checks full? No, MatchString checks if string contains match? With "^", it checks prefix. Good.
		// For "*" wildcard: "*" matches any sequence (including "/"? Yes).
		hasEnd := strings.HasSuffix(pattern, "$")
		pat := pattern
		if hasEnd {
			pat = pat[:len(pat)-1] // strip trailing "$"
		}
		// Escape regex meta: . + ? ^ $ ( ) [ ] { } | \ . But "*" is wildcard, keep.
		var sb strings.Builder
		sb.WriteString("^")
		for _, c := range pat {
			if c == '*' {
				sb.WriteString(".*")
			} else if strings.ContainsRune(`.+?^$()[]{}|\`, c) {
				sb.WriteRune('\\')
				sb.WriteRune(c)
			} else {
				sb.WriteRune(c)
			}
		}
		if hasEnd {
			sb.WriteString("$")
		}
		// Compile and match? Cache? For simplicity, compile each time (robots checked per URL, could be many, but okay for small).
		// To avoid recompiling, we could use simple matching without regex for common cases, but okay.
		re, err := regexp.Compile(sb.String())
		if err != nil {
			// Fallback to prefix?
			return strings.HasPrefix(path, pattern)
		}
		return re.MatchString(path)
	}
	// Simple prefix match (case-sensitive)
	return strings.HasPrefix(path, pattern)
}

// robotsPathForURL returns path + "?" + query for robots checking (without fragment, without host).
// urlStr is full URL string? Or parsed? We'll take path and query from parsed URL.
func robotsPath(path, query string) string {
	if query != "" {
		return path + "?" + query
	}
	if path == "" {
		return "/"
	}
	return path
}
