package main

import (
	"bufio"
	"context"
	"crypto/tls"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"sync"
	"time"
)

// Semaphore to match original panic/deadlock behavior
type semaphore chan struct{}

func newSemaphore(n int) semaphore {
	return make(semaphore, n)
}

func (s semaphore) Request() {
	s <- struct{}{}
}

func (s semaphore) Release() {
	<-s
}

type hostThrottlerPool struct {
	mu sync.Mutex
	m map[string]semaphore
	size int
}

func newHostThrottlerPool(size int) *hostThrottlerPool {
	return &hostThrottlerPool{m: make(map[string]semaphore), size: size}
}

func (p *hostThrottlerPool) Get(host string) semaphore {
	p.mu.Lock()
	defer p.mu.Unlock()
	if s, ok := p.m[host]; ok {
		return s
	}
	s := newSemaphore(p.size)
	p.m[host] = s
	return s
}

type rateLimiter struct {
	mu sync.Mutex
	last time.Time
	rate int // per second, <=0 means no limit
}

func (r *rateLimiter) Wait() {
	if r.rate <= 0 {
		return
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	interval := time.Second / time.Duration(r.rate)
	now := time.Now()
	if !r.last.IsZero() {
		elapsed := now.Sub(r.last)
		if elapsed < interval {
			time.Sleep(interval - elapsed)
			now = time.Now()
		}
	}
	r.last = now
}

type fetcher struct {
	opts *options
	accepted []acceptedEntry
	client *http.Client
	transport *http.Transport
	globalSem semaphore
	hostPool *hostThrottlerPool
	rate *rateLimiter
	resolver *net.Resolver // custom if dnsResolver set, else nil (use default)
	proxyAddr string // parsed proxy host:port (without scheme), or "" if no proxy
	proxyHost string
	proxyPort int
