	// Non-retryable: "timeout"? Our earlier test showed timeout not retried (only 1 hit). So timeout should be non-retryable? Or retryable but original didn't retry? Let's treat timeout as non-retryable to match observed (1 hit). Good.
	if msg == "timeout" {
		return false
	}
	if strings.HasPrefix(msg, "parse \"") || strings.HasPrefix(msg, "parse '") {
		return false
	}
	if msg == "missing port in address" || strings.HasPrefix(msg, "address ") {
		return false
	}
	if strings.HasPrefix(msg, "unsupported protocol") {
		return false
	}
	if msg == "location header not set" || msg == "too many redirections" || msg == "body size exceeds the given limit" {
		return false
	}
	if strings.HasPrefix(msg, "could not connect to proxyAddr:") {
		return false
	}
	if strings.HasPrefix(msg, "strconv.Atoi:") || strings.HasPrefix(msg, "strconv.Parse") {
		return false
	}
	if strings.HasPrefix(msg, "error when reading response headers:") {
