func (c *crawler) isExcluded(urlStr string) bool {
	for _, re := range c.excludeRes {
		if re.MatchString(urlStr) {
			return true
		}
	}
	if len(c.includeRes) > 0 {
		matched := false
		for _, re := range c.includeRes {
			if re.MatchString(urlStr) {
				matched = true
				break
			}
		}
		if !matched {
			return true
		}
	}
	return false
