				if ai.isSuccess != aj.isSuccess {
					return ai.isSuccess && !aj.isSuccess
				}
				var ri, rj string
				if ai.isSuccess {
					ri = fmt.Sprintf("%d", ai.status)
				} else {
					ri = ai.errMsg
				}
				if aj.isSuccess {
					rj = fmt.Sprintf("%d", aj.status)
				} else {
					rj = aj.errMsg
				}
				if ri != rj {
					return ri < rj
				}
				return ai.url < aj.url
			})
			tests := len(links)
			failures := 0
			for _, l := range links {
				if !l.isSuccess {
					failures++
				}
			}
			escPageURL := xmlEscape(p.url)
			if tests == 0 {
				fmt.Fprintf(os.Stdout, "  "+`<testsuite name="%s" tests="0" failures="0" skipped="0"></testsuite>`+"\n", escPageURL)
			} else {
				fmt.Fprintf(os.Stdout, "  "+`<testsuite name="%s" tests="%d" failures="%d" skipped="0">`+"\n", escPageURL, tests, failures)
				for _, l := range links {
					escLinkURL := xmlEscape(l.url)
					if l.isSuccess {
