func xmlEscape(s string) string {
	// Match Go's encoding/xml escaping for attributes.
	// Go's xml.EscapeText escapes: " -> &#34;, ' -> &#39;, & -> &amp;, < -> &lt;, > -> &gt;, \t -> &#x9;, \n -> &#xA;, \r -> &#xD; ?
	// Actually need to check. For JUnit failure message with \r\n (from buffer error headers), original output showed \r\n preserved? Let's look at raw: earlier JUnit for buffer error had `message="... HTTP/1.0 200 OK\r\nServer: ...` – In our terminal, \r\n appeared as actual line break? Or as \r\n characters? The output we saw (via cat) showed one line with `...`? Hard to tell. Let's implement escaping that matches Go's xml.Marshal for attributes.
	// Simplest: use strings.Replacer for &, <, >, ", ', \t, \n, \r.
	// Order: & first (to avoid double-escaping).
	r := strings.NewReplacer(
		`&`, "&amp;",
		`<`, "&lt;",
		`>`, "&gt;",
		`"`, "&#34;",
		`'`, "&#39;",
		"\t", "&#x9;",
		"\n", "&#xA;",
		"\r", "&#xD;",
	)
	return r.Replace(s)
}

